-- Russian for NPC lines and greetings of the Forever era: a Russian client saw them in English (GitHub #12, cyborgx5, 2026-11-16:
-- Tirisfal, "Get away from me, monster!", the paladin trainer's "Welcome back to the light, friend..."). These broadcast texts came
-- with the beta sniff hotfixes (2026_10_01_02 and later) in English only, so the server answered a Russian client's request with
-- the English record. 337 of the 1321 broadcast texts without Russian get it here.
-- Data: Russian text from the Azeroth project (Sakhwoow/WoWForever, GPL-2, branch forever, head 637626e, 2026-11-15): their ruRU
-- sniffs of the Forever beta and live (Undead start, paladin start, player caches) and their own translations. Taken only where
-- our English line is word for word the same as theirs, and only where we have no Russian at all (a line whose English names the
-- player with $n and whose Russian does not is left out: a baked-in player name). Fills gaps only; safe to run again.

INSERT IGNORE INTO `broadcast_text_locale` (`ID`,`locale`,`Text_lang`,`Text1_lang`,`VerifiedBuild`) VALUES
(212752,'ruRU','Знание может быть как инструментом, так и оружием.','Знание может быть как инструментом, так и оружием.',0),
(245462,'ruRU','','Я занимаюсь тонкими делами разведки Орды. Для нас обоих будет лучше, если ты не станешь меня отвлекать.',0),
(250597,'ruRU','','У нас пропадают грузы по всему Азероту. Если найдешь какой-нибудь, буду признателен, если вернешь его мне.',0),
(290401,'ruRU','С возвращением к Свету, друг. Тебе требуется обучение?','С возвращением к Свету, друг. Тебе требуется обучение?',0),
(290402,'ruRU','Хоть ты и не паладин, но если пожелаешь, то еще можешь найти утешение у Света.','Хоть ты и не паладин, но если пожелаешь, то еще можешь найти утешение у Света.',0),
(292197,'ruRU','','Прочь, чудовище!',0),
(292198,'ruRU','','Нет! Нет-нет-нет! Отрекшаяся? Лучше смерть! 
\n
\n<Испуганный паладин поднимает оружие и готовится к атаке!>',0),
(292201,'ruRU','Свет – это путеводная звезда, сияющая для нас всех. Чем могу помочь тебе, |3-6($c)?','Свет – это путеводная звезда, сияющая для нас всех. Чем могу помочь тебе, |3-6($c)?',0),
(292461,'ruRU','','Добро пожаловать в крепость Бандариона, $c.',0),
(292462,'ruRU','В прошлой жизни мой дом был неподалеку отсюда. Я до сих пор иногда брожу по полям родной фермы. Мне грустно видеть, как те, кто был мне знаком и дорог, бродят безмозглыми рабами. Это больно, но именно боль дает мне силу и цель.','',0),
(292463,'ruRU','','Почему меня зовут «Крушительница»?
\n
\nПоверь, тебе лучше не знать.',0),
(292477,'ruRU','Во тьме таится много всего, и Свет нужен сейчас как никогда. Если бы эти бедняги поняли: то, что наш мир изменился, не значит, что мы должны быть теми чудовищами, какими нас считают живые.','',0),
(292949,'ruRU','Здравствуй, $n! Не $gдумал:думала; о том, чтобы освоить какую-нибудь профессию?
\n
\nЯ с радостью отвечу на любые вопросы или подскажу, где найти местных учителей.
\n
\nЕсли тебе все это кажется слишком сложным, не переживай! Ты всегда можешь вернуться сюда или заглянуть к учителям в столицах, чтобы начать свой путь в ремеслах в любое время.','Здравствуй, $n! Не $gдумал:думала; о том, чтобы освоить какую-нибудь профессию?
\n
\nЯ с радостью отвечу на любые вопросы или подскажу, где найти местных учителей.
\n
\nЕсли тебе все это кажется слишком сложным, не переживай! Ты всегда можешь вернуться сюда или заглянуть к учителям в столицах, чтобы начать свой путь в ремеслах в любое время.',0),
(292959,'ruRU','Я рад, что ты спросил!
\n
\nПрофессии – это навыки, связанные с созданием предметов, добычей ресурсов и выживанием. Их много, и у каждой свои уникальные преимущества и возможности для заработка. Хочешь разбогатеть, пополнить склад гильдии полезными вещами или просто получать удовольствие от снаряжения, сделанного своими руками, – для всего этого найдется своя профессия.
\n
\nРецепты можно изучить у учителей, таких как местные, и во множестве других мест Азерота. Выучив рецепт, ты сможешь создавать сколько угодно таких предметов, если, конечно, достанешь необходимые материалы.','Я рад, что ты спросил!
\n
\nПрофессии – это навыки, связанные с созданием предметов, добычей ресурсов и выживанием. Их много, и у каждой свои уникальные преимущества и возможности для заработка. Хочешь разбогатеть, пополнить склад гильдии полезными вещами или просто получать удовольствие от снаряжения, сделанного своими руками, – для всего этого найдется своя профессия.
\n
\nРецепты можно изучить у учителей, таких как местные, и во множестве других мест Азерота. Выучив рецепт, ты сможешь создавать сколько угодно таких предметов, если, конечно, достанешь необходимые материалы.',0),
(292961,'ruRU','Профессии делятся на две главные категории: основные и вспомогательные.
\n
\nМожно получить только две основные профессии. В любой момент разрешено отказаться от одной из профессий, но все полученные знания при этом будут утрачены. Если же вернуться к забытой профессии, придется изучать все с нуля и собирать рецепты повторно.
\n
\nУ вспомогательных профессий нет такого ограничения. Цель этих навыков – основы выживания без чужой помощи. Все вспомогательные профессии можно прокачивать одновременно, но они почти не будут приносить прибыли.','Профессии делятся на две главные категории: основные и вспомогательные.
\n
\nМожно получить только две основные профессии. В любой момент разрешено отказаться от одной из профессий, но все полученные знания при этом будут утрачены. Если же вернуться к забытой профессии, придется изучать все с нуля и собирать рецепты повторно.
\n
\nУ вспомогательных профессий нет такого ограничения. Цель этих навыков – основы выживания без чужой помощи. Все вспомогательные профессии можно прокачивать одновременно, но они почти не будут приносить прибыли.',0),
(292988,'ruRU','Конечно! К какой профессии мне тебя направить?
\n
\nЯ отмечу на твоей карте местоположение выбранного тобой учителя поблизости. Помни, что в столицах ты найдешь учителей, которые смогут обучить тебя более полно.','Конечно! К какой профессии мне тебя направить?
\n
\nЯ отмечу на твоей карте местоположение выбранного тобой учителя поблизости. Помни, что в столицах ты найдешь учителей, которые смогут обучить тебя более полно.',0),
(293818,'ruRU','Хочешь научиться снимать шкуры с убитых зверей? Или тебе нужны новые инструменты?','Хочешь научиться снимать шкуры с убитых зверей? Или тебе нужны новые инструменты?',0),
(296872,'ruRU','Что брату Пакстону нужно на этот раз?','Что брату Пакстону нужно на этот раз?',0),
(299234,'ruRU','','Хвала Королеве-банши, гости у меня здесь бывают нечасто.',0),
(299774,'ruRU','<Подойдя к громадному циклонному голему, вы слышите тихое жужжание из-под его массивных доспехов. Если прислушаться повнимательнее, можно разобрать несколько осмысленных слогов, но искаженный звук мешает понять слова.>','<As you approach the enormous cyclone construct, you hear a faint buzzing emanating from beneath its massive armor plates. If you listen carefully, you think you might be able to hear a few words being formed but they are too distorted to make out.>',0),
(299873,'ruRU','','Здравствуй, |3-6($c).',0),
(300037,'ruRU','П-привет. Не обижайся, пожалуйста. Ваши обычно от меня убегают.','',0),
(300039,'ruRU','That is... a very good question. I have a hard time remembering things, but I do remember something... "Engineer", perhaps? I think that''s what, or who, I was.
\n
\nOther than that, all I can seem to remember is soaring through the sky, then seeing a flash of lightning before things got very bumpy. Then... a crash.
\n
\nIt''s been... a long time though. A very long time.','',0),
(300042,'ruRU','Эти? Я их построил. А мои маленькие друзья помогали. У меня с памятью плохо, но я знаю, что когда-то я много всего выстроил. Огромных размеров! Но потом... я оказался тут, да-да. Теперь мои поделки гораздо мельче и невзрачнее. Но меня они все равно развлекают, ха!
\n
\nН-но... Если хочешь, я научу строить и тебя!','',0),
(300516,'ruRU','','С чего начать? Наш дом на грани краха. Обереги разрушились, и три провинции расходятся все дальше друг от друга. Когда-то шпили Шен''драмара было видно с западной дозорной башни. Теперь уже нет. Опорные столпы ветшают, и если цепи наконец порвутся...',0),
(300517,'ruRU','','В чем причина? Если коротко, духи ветра просто... исчезли. Вчера они были, а сегодня их нет. Не описать, что Ваятели Ветра испытали в тот миг. Нас как будто накрыла непроницаемая тишина, а потом... безмерная пустота.
\n
\nЖалкие фантомы, которые тебе наверняка уже встречались, не более чем тени величия настоящих духов ветра. Эти неразумные существа блуждают без цели и смысла: бледная пародия на верных друзей, с которыми мы тысячи лет жили в гармонии.',0),
(300518,'ruRU','','Many disagree on this point. I believe that simple communication is the key. The songs of the wind rang so clearly to us when the spirits were still here. Since they left, it''s grown quiet and our power as windshapers has weakened. 
\n
\nHowever, there are those of us who can still hear something. A hushed tone. Fragments of a melody. Those that can still hear and see into the elemental planes must grow in strength. I believe that is the key to our salvation.',0),
(300519,'ruRU','','Культ? Кучка фанатиков и убийц. Они верят, что мы понесли кару за какой-то неведомый грех. На самом же деле их лидеры – обыкновенные жулики из бывшего ордена сомнительных "жрецов" Ал''акира Владыки Ветра.
\n
\nОни увидели возможность сыграть на страхах нашего народа, чтобы пробиться к власти... И долго раздумывать не стали.',0),
(300520,'ruRU','','За все годы нашей дружбы с духами ветра они ни разу не выражали к Владыке Ветра никакого благоговения. Да, упоминали о существовании Ал''акира, но избегали произносить его имя – словно бы в страхе перед ним.
\n
\nДаже если этот Ал''акир – всемогущий "Владыка Ветра" или правитель элементалей воздуха, века жизни бок о бок с духами убедили меня, что он как минимум не самая популярная личность среди обитателей Небесной выси. Боюсь, что попытки договориться с Ал''акиром лишь приблизят наш роковой конец.',0),
(300521,'ruRU','','Не забывай, что здесь мы никогда не обретем настоящий дом, пусть даже это измерение приютило нас на многие века. Мы не в земном мире, где появились на свет. Мы в царстве Небесной выси, одной из сфер стихий.
\n
\nПрибыли сюда по приглашению духов, с которыми сроднились в древние времена. Теперь шен''дорай лишились их дружбы – а может, и защиты. Неизвестно, как нас воспримут другие обитатели этого измерения.',0),
(300522,'ruRU','','Alas, I have prattled on long enough. Seek out my apprentice Ayessa Dawnsinger in the port of Valanaar if you find yourself out that way. She still hears the song--if only faintly. I am old and much of my power has left me. Ayessa represents the future of our people and the path we must now walk to survive. It''s up to her and young skyborne such as yourself to carry the hopes for our people forward.',0),
(300621,'ruRU','<Бурлящее облако живых молний угрожающе потрескивает, когда вы подходите ближе. Наверное, лучше уйти. И побыстрее.>','<Бурлящее облако живых молний угрожающе потрескивает, когда вы подходите ближе. Наверное, лучше уйти. И побыстрее.>',0),
(300626,'ruRU','','Здравствуй, |3-6($c). Хочешь заслужить благословение Владыки Ветра?',0),
(300634,'ruRU','Благословение Повелителя ветров течет сквозь меня!','Благословение Повелителя ветров течет сквозь меня!',0),
(300635,'ruRU','Ты $Gслышал:слышала; благую весть об Ал''акире, Повелителе ветров?','Ты $Gслышал:слышала; благую весть об Ал''акире, Повелителе ветров?',0),
(300636,'ruRU','Неверные будут очищены в наших славных бурях! Хвала Повелителю ветров!','Неверные будут очищены в наших славных бурях! Хвала Повелителю ветров!',0),
(300637,'ruRU','Бьется ли твое сердце в такт ветрам?','Бьется ли твое сердце в такт ветрам?',0),
(300638,'ruRU','Скоро шен''дорай узрят истину... А слепцов сметет грядущая буря!','Скоро шен''дорай узрят истину... А слепцов сметет грядущая буря!',0),
(300661,'ruRU','Добро пожаловать! Впервые в городе? Как освоишься, приходи ко мне – скажу, где можно будет подзаработать. Я с ног валюсь от подготовки к Фестивалю Ветров. Соглашусь на любую помощь, лишь бы кладовые не пустели.','',0),
(300662,'ruRU','Если подумываешь научиться готовить, могу дать парочку советов! Хо-хо! Надевай передник и за дело!','',0),
(300663,'ruRU','','Здравствуй, дитя. Я Иллайя Янтарный Ветер, старейшина Ваятелей Ветра на острове Зефрис. Мы всегда рады новым гостям из рощи.
\n
\nНе бойся, старая шаманка не будет отнимать у тебя время. Тебе наверняка пора отправляться в очередное странствие. Заходи попозже, когда пожелаешь.',0),
(300665,'ruRU','','Я руковожу делами деревни Шен''дар, и здесь очень многое нужно держать под контролем. Бандиты, сектанты и прочие неожиданные происшествия – чтобы эта деревня держалась на плаву, приходится немало потрудиться.',0),
(300678,'ruRU','','<Констебль Аонда о чем-то напряженно размышляет.>',0),
(300698,'ruRU','Я могу научить тебя делать роскошную кожаную броню, если не будешь лениться.','',0),
(300702,'ruRU','','Портные-шен''дорай в своей работе вдохновляются легкостью текущих потоков ветра. Духи нас покинули, и я не знаю, когда снова увижу их танец... Но мое ремесло утешает меня, хоть и отвлекает лишь на время.
\n
\nЕсли хочешь, я научу тебя тоже работать с тканью.',0),
(300714,'ruRU','<Труп покрывают ожоги и красные пятна. Он что-то сжимает в руках.>','<Труп покрывают ожоги и красные пятна. Он что-то сжимает в руках.>',0),
(301009,'ruRU','Здравствуй, |3-6($c). Добро пожаловать в залы торговой гильдии. Запасы на Зефрисе сейчас оскудели, но здесь ты найдешь столько материалов и товаров, что без труда продолжишь свои приключения.
\n
\nЕсли будут вопросы, не стесняйся и задавай.','Здравствуй, |3-6($c). Добро пожаловать в залы торговой гильдии. Запасы на Зефрисе сейчас оскудели, но здесь ты найдешь столько материалов и товаров, что без труда продолжишь свои приключения.
\n
\nЕсли будут вопросы, не стесняйся и задавай.',0),
(301019,'ruRU','Подойди, дитя. Сядь рядом.','',0),
(301020,'ruRU','Столпы удерживают наш родной остров в мире стихий Небесной выси. Теперь они ветшают, и Зефрис в страшной опасности.','',0),
(301021,'ruRU','Культ Ал''акет становится все агрессивнее. А Ваятели ветра упрямо отказываются признавать, что всему виной их бездействие.','',0),
(301024,'ruRU','Мы совершили фатальную ошибку, когда доверили свою судьбу переменчивым духам стихий. Теперь нам предстоит ее исправить.','',0),
(301025,'ruRU','','Как ты наверняка помнишь, духи подарили нам столпы ветра, которые связывают нас с миром стихий Небесной выси. Сейчас эти столпы ветшают, и нашему дому грозит катастрофа.',0),
(301026,'ruRU','','Как будешь проходить мимо порта Валанаара, найди Айессу Певицу Рассвета. Она расскажет подробнее.',0),
(301027,'ruRU','','Культ Ал''акет заходит все дальше в своей агрессии. А бездумное применение магии, которое так любит Высший орден, может приблизить нас к гибели.',0),
(301028,'ruRU','','The Windshapers possess the gift of skysight, and we are working tirelessly to find our lost elemental benefactors, so that they may guide us once again.',0),
(301029,'ruRU','','Магия шаманов сильно ослабла после исчезновения духов, но мы твердо намерены вернуть их домой.',0),
(301030,'ruRU','','Мы не отступим, пока не выясним причину. Мы найдем в себе силу призвать духов обратно.',0),
(301031,'ruRU','','Будущее нашего народа скрывается в тумане, но надежда еще живет, и у нас есть план...',0),
(301032,'ruRU','С чего начать? Наш дом на грани краха. Обереги разрушились, и три провинции расходятся все дальше друг от друга. Когда-то шпили Шен''драмара было видно с западной дозорной башни. Теперь уже нет. Столпы ветра, которые удерживают нас в этих сферах, ветшают с каждым днем...','',0),
(301033,'ruRU','В чем причина? Если коротко, духи ветра просто... исчезли.
\n
\nЖалкие фантомы и мелкие элементали, которые тебе наверняка уже встречались, не более чем тусклые подобия настоящих духов ветра. Эти неразумные существа блуждают без цели и смысла: бледная пародия на верных друзей, с которыми мы тысячи лет жили в гармонии.','',0),
(301034,'ruRU','По этому поводу идут споры. Послушать Ваятелей Ветра – можно просто взяться за руки и надеяться на возвращение духов. Но власть их общины иссякает, а образ жизни зависит от того же цикла взаимозависимости, который и привел нас к краху. Высший же орден... предпочитает более прямой подход.','',0),
(301035,'ruRU','Культ? Кучка фанатиков и убийц. Они верят, что мы понесли кару за какой-то неведомый грех. На самом же деле их лидеры – обыкновенные жулики из бывшего ордена сомнительных "жрецов" Ал''акира Владыки Ветра.
\n
\nОни увидели возможность сыграть на страхах нашего народа, чтобы пробиться к власти... И долго раздумывать не стали.','',0),
(301036,'ruRU','Даже Ваятели Ветра тебе скажут, что духи ветра никогда не выказывают своим правителям особого почета. Они упоминали о существовании Ал''акира, но избегали произносить его имя – словно бы в страхе перед ним.
\n
\nДаже если этот Ал''акир – всемогущий "Владыка Ветра" или правитель элементалей воздуха, зависимость от элементалей как раз и вышла нам боком. Пора исправлять ситуацию своими силами.','',0),
(301037,'ruRU','You must remember that while this realm has been our home for millennia, we will always be somewhat alien to this place. We are not in the terrestrial world that birthed our people. We are in the realm of Skywall, the elemental plane of air.
\n
\nWe arrived here as the guests of spirits with whom we found kinship in ages past. Now that we shen''dorei find ourselves bereft of their presence--and potentially--their protection, there''s no telling how the other denizens of this plane may perceive us.','',0),
(301038,'ruRU','Но хватит мне молоть языком. Найди Элаадрина Вечерняя Буря в порту Валанаара, если будешь проходить мимо. Элаадрин – мой бывший ученик. Теперь он занимает пост главного магистра Высшего ордена. У него сильная воля и большой талант в магии. Наш народ возлагает надежды на него и юных небеснорожденных вроде тебя.','',0),
(301040,'ruRU','','Если ищешь работу, многие из местных тоже ищут помощника для всевозможных поручений. Просто походи и поспрашивай – обязательно что-нибудь найдешь.',0),
(301044,'ruRU','Hello there, young $c. I am Rathiril Sunlance and I am an elder Magister of the High Order here on Zephras Isle. It''s always good to see bright-eyed young shen''dorei, ready to do their duty in service to their homeland.
\n
\nDon''t let this dusty old mage hold you up, however. No doubt you''ve got many adventures to see to. Feel free to stop by later if you''d like to speak more.','',0),
(301355,'ruRU','Мы с женой держим буреяблочный сад в низинах к западу от Валанаара.','',0),
(301356,'ruRU','Несколько лет назад на нашу ферму напали бандиты. Они вынесли все подчистую и избили меня до полусмерти. На следующий год, в тот же сезон, они вернулись.','',0),
(301357,'ruRU','Они опять забрали большую часть урожая, но главарь бандитов... Ферау Верзила, как он себя называет... сказал, что они будут возвращаться каждый сезон и брать вдвое против предыдущего года.','',0),
(301358,'ruRU','Мы обращались к миротворцам с просьбой отвадить бандитов, но из-за культа у них совершенно не осталось свободных солдат.','',0),
(301359,'ruRU','В этом году буреяблоки уродились плохо, и нам почти нечем им заплатить. В лучшем случае они просто убьют нас быстро. Но вероятнее, что отберут все и обрекут на голодную смерть.','',0),
(301362,'ruRU','Я пришел в город нанять бойцов, чтобы прогнать их. Один согласился, но сразу же ограбил меня на выходе из города и чуть не убил.','',0),
(301364,'ruRU','Я страдаю от ран и не могу даже встать с постели. Умоляю тебя – найди мой сад, расскажи все Аамелии и помоги ей выжить. Пожалуйста... помоги нам.','',0),
(301399,'ruRU','','Сад Поля Ветров переживает не лучшие времена...',0),
(301445,'ruRU','Аамелия, дорогуша! Где Альварион? Испугался Ферау и послал тебя?','',0),
(301446,'ruRU','','Альварион? Он с миротворцами, зачищает холмы от твоих прихвостней. Они вернутся с минуты на минуту и очень тебе обрадуются.',0),
(301447,'ruRU','HA! A poor bluff! Ferauu has eyes and ears everywhere. I know that it''s just you and this scrawny stranger here. You''ve had your fun putting down a few of my weaker recruits, but The Bludgeon is here now and the party is over. Time to pay up, with interest.','',0),
(301448,'ruRU','','Что-то я заболталась. Спасибо тебе за все...',0),
(301449,'ruRU','','Аамелия поднимает вилы в угрожающей позе.',0),
(301450,'ruRU','','Хм... Неожиданный поворот. Ну зато мы теперь знаем, зачем нужна эта штуковина. Давай вернемся в дом.',0),
(301451,'ruRU','','Здравствуй! Я Сания Серебряный Поток – миссионер и верная слуга нашего всемогущего господина Ал''акира Владыки Ветра.
\n
\nАл''акетов презрительно называют жестокой "сектой", но на самом деле мы стремимся к миру и просветлению. Наш господин Ал''акир – величайший правитель Небесной выси, и лишь его милостью мы спасемся от бед, постигших наш народ.
\n
\nЕсли тебе интереснее хорошие новости, приходи ко мне когда захочешь. Да благословит тебя Владыка Ветра.',0),
(301455,'ruRU','<Лежащий мужчина неловко дергается. Он выздоравливает после очень неприятных ран.>','',0),
(301456,'ruRU','Всегда рад видеть тебя, $n.','',0),
(301472,'ruRU','Если ты от Ратирила, то уже понимаешь, какой кризис мы сейчас переживаем.','',0),
(301473,'ruRU','Высший орден ищет прагматичное и цивилизованное решение нашего кризиса.','',0),
(301474,'ruRU','Которое не уповает на чудесное спасение от сторонних сил. Надо самим ковать свою судьбу – впервые с переселения в Небесную высь.','',0),
(301475,'ruRU','Since we left our homes in Kalimdor, the world has grown. They call it "Azeroth" now and it''s a massive, vibrant world.','',0),
(301476,'ruRU','Недавно мы сумели прорезать своего рода "замочную скважину", которая позволила нам заглянуть между измерениями и многое узнать об Азероте.','',0),
(301478,'ruRU','Когда мы заглянули в эту замочную скважину, кто-то смотрел с той стороны. Маги из похожего ордена, который называется Кирин-Тор. Мы очень многое от них узнали.','',0),
(301480,'ruRU','Элементали, которые привели нас сюда, исчезли. Любые их чары, оберегавшие наш дом, можно заменить магией высокорожденных. Но в Небесной выси наша сила угасла.','',0),
(301481,'ruRU','Кому-то из нас нужно оставить это измерение и отправиться на Азерот. Там мы вновь обретем утраченные знания и вернемся сюда, чтобы спасти наш дом.','',0),
(301482,'ruRU','Кирин-Тор любезно согласился принять нас как гостей, и их помощь будет незаменима для наших целей.','',0),
(301483,'ruRU','Нам понадобятся исследователи и первооткрыватели всех мастей. Подумай над моим предложением. Надеюсь, ты присоединишься к нам, когда придет время. А пока – удачи.','',0),
(301833,'ruRU','','Что-то не так... Почему нет взрыва?',0),
(301834,'ruRU','Взрыва не будет. Я дал тебе нерабочий детонатор.','',0),
(301835,'ruRU','','Что? Почему?',0),
(301836,'ruRU','Теперь этим займется ШРУ. Освобожденная у Братства Справедливости кузня и корабль обладают стратегической важностью. Мы берем их под свой контроль.','',0),
(301837,'ruRU','','Ты не понимаешь. Эта кузня отравляет фермы Западного Края! Если ее не уничтожить, тут несколько поколений ничего не будет расти. Народ останется без пищи!',0),
(301838,'ruRU','Благодарю за беспокойство, эльф, но теперь это внутреннее дело Штормграда. Твоя помощь больше не нужна.','',0),
(301839,'ruRU','<Небеснорожденный лежит без сознания.>','<Небеснорожденный лежит без сознания.>',0),
(301843,'ruRU','Мм-м... что... что происходит? Что это?..','',0),
(301844,'ruRU','My... head... ohh it hurts! What... who are you? Why... are you carrying me?','',0),
(301845,'ruRU','Пожалуйста... Положи меня... На те одеяла у дерева...','',0),
(301874,'ruRU','It is encouraging to know that Elaadrin and his mages are finally with us. With both the High Order and the Windshapers working with us against the greater threat, we stand a much better chance to thwart the Al''Aketh and whatever they have planned for Valanaar.','',0),
(301876,'ruRU','Что касается тебя, |3-6($c). Я слышал про стычку с Ваятелями Ветра у каменных монолитов...','',0),
(301877,'ruRU','Возмездие еще свершится. А пока надеюсь, что Ваятели Ветра с Высшим орденом согласятся объединиться против культа. Сейчас Ал''акет – главная угроза Зефрису.','',0),
(301916,'ruRU','<Сектант мертв. Осмотрев его внимательно, вы замечаете, что он оберегающим жестом прижимает что-то к груди.>','<Сектант мертв. Осмотрев его внимательно, вы замечаете, что он оберегающим жестом прижимает что-то к груди.>',0),
(302043,'ruRU','Приветствую.','Здравствуйте.',0),
(302044,'ruRU','Что вы ищете?','Что вы ищете?',0),
(302046,'ruRU','Вам помочь что-то найти?','Вам помочь что-то найти?',0),
(302047,'ruRU','Могу я помочь вам в поисках?','Могу я помочь вам в поисках?',0),
(302063,'ruRU','','Большая часть острова подвергается безнаказанным бесчинствам сектантов, поэтому Лортуна думает, что мы теряем контроль над ситуацией. Можно сыграть на ее самоуверенности.',0),
(302064,'ruRU','','Если провести отвлекающий маневр у святилища, небольшой отряд миротворцев, Ваятелей Ветра и Высшего ордена сумеет пробить фланг и прорваться к внутреннему алтарю. А там мы ликвидируем саму верховную жрицу и отрубим змее голову.',0),
(302065,'ruRU','','Поговори сначала с лидером Ваятелей Ветра, а потом – Высшего ордена. Они недолюбливают друг друга, но у них хватит ума понять, что сейчас важнее борьба с Ал''акетом. Уговори их поддержать план и возвращайся ко мне.',0),
(302068,'ruRU','','Если бы Высший орден хоть немного думал о решении наших настоящих проблем и меньше помешался на древней магии, нам, как народу, было бы гораздо лучше. Именно магия высокорожденных погубила калдорай в свое время. И эти самовлюбленные глупцы хотят повторить те же ошибки!
\n
\nОдно то, что они пытались договориться с культом, уже плохо, но пролить кровь Ваятелей ветра – вот что воистину непростительно. Если бы не нависшая угроза культа, я бы собрал наши силы и покончил с Элаадрином и Высшим орденом раз и навсегда.',0),
(302070,'ruRU','','Айесса Певица Рассвета смеривает вас взглядом, едва сдерживая гнев.> 
\n
\nНа твоих руках кровь Ваятелей Ветра. Заявиться сюда после такого может или исключительный храбрец, или исключительный глупец. Мы нескоро прощаем и ничего не забываем.
\n
\nНа твоем месте я бы убралась отсюда. Твое счастье, что я не хочу тебя убивать на виду у всего Зефриса.',0),
(302073,'ruRU','','Хм... Ясно. Ну хорошо, |3-6($c). Ваятели Ветра поддержат план. Передай Валеннии, что в этот раз она может на нас рассчитывать.
\n
\n<Айесса угрожающе понижает голос.> 
\n
\nНе путай поддержку с прощением. На тебе кровавый долг, и однажды мы придем за расплатой.',0),
(302079,'ruRU','Здравствуй. Я Элаадрин Вечерняя Буря, верховный магистр Высшего ордена. Чем могу помочь?','',0),
(302085,'ruRU','The Windshapers are almost wholly to blame for everything that has happened. Their refusal to change has damaged our ability to save ourselves from our current peril. They speak in absolutes and treat assumptions and superstitious hope as fact.
\n
\nDo you know who else deals only in absolutes? The Al''Aketh. 
\n
\nI for one do not intend to let blind adherence to dangerous beliefs doom our people. If it weren''t for the threat of the cult, I''d march our mages over to the other side of Valanaar and wipe the Windshapers out.','',0),
(302087,'ruRU','Ясно. Мы идем на огромный риск, но в нашем положении выбирать не приходится.
\n
\nХорошо, Ваятели Ветра поддержат план. Передай Валеннии, что в этот раз она может на нас рассчитывать.','',0),
(302089,'ruRU','<Элаадрин смотрит на тебя с едва сдерживаемой ненавистью.> 
\n
\nТы смеешь ступать в наше святилище после того, как $Gпролил:пролила; кровь Высшего ордена? Ты очень $Gхрабрый:храбрая; или очень $Gглупый:глупая;. Высший орден не прощает и не забывает.
\n
\nКогда-нибудь ты заплатишь за свои преступления кровью.','',0),
(302093,'ruRU','Миротворцы сами понимают, что у них недостает сил для открытого нападения на святилище. Без подкреплений от Ваятелей Ветра и Высшего ордена у нас нет шансов. Обе фракции поклялись протянуть руку помощи в ответ на наш призыв. Удар надо нанести сейчас.
\n
\nК сожалению, недавно конфликт между ними перерос в кровопролитие, и примирить их будет тяжело.
\n
\nКак насчет небольшой дипломатической миссии?','Миротворцы сами понимают, что у них недостает сил для открытого нападения на святилище. Без подкреплений от Ваятелей Ветра и Высшего ордена у нас нет шансов. Обе фракции поклялись протянуть руку помощи в ответ на наш призыв. Удар надо нанести сейчас.
\n
\nК сожалению, недавно конфликт между ними перерос в кровопролитие, и примирить их будет тяжело.
\n
\nКак насчет небольшой дипломатической миссии?',0),
(302159,'ruRU','','<Валенния тяжело ранена. Ей стоит большого труда не упасть в обморок.>',0),
(302160,'ruRU','','Most of the cultists at the Sanctum of Storms seem to have come out to respond to our attack. I never would have expected this to go so well. This was almost too easy...
\n
\nI think that the Windshapers and High Order have made their push. Valennia should be with them. You should head inside and find her. We''ll stay here and keep watch while Valennia and the others finish what they came here to do.',0),
(302282,'ruRU','You''ll need to speak with Skypriest Aanders for instruction. There is no guidance I can provide. Be gone with you, recruit.','You''ll need to speak with Skypriest Aanders for instruction. There is no guidance I can provide. Be gone with you, recruit.',0),
(302443,'ruRU','Мы пришли, как только нам сообщили новости. Высший орден готов служить Зефрису.','',0),
(302444,'ruRU','','...И Ваятели Ветра. Мы поддержим нападение на святилище, Валенния.',0),
(302445,'ruRU','','Благодарю. По правде говоря, мы ведем опасную игру и не обязательно выиграем. Надо понимать, что тебе может выпасть билет в один конец.',0),
(302446,'ruRU','','Мы-то понимаем. К слову, я встретилась с Элаадрином и мы распорядились послать за... помощью со стороны. Неизвестно, придет она вовремя или нет. А может, не придет вовсе...',0),
(302447,'ruRU','','Со... стороны? Из других провинций? Мы потеряли связь с остальными островами много лет назад!',0),
(302448,'ruRU','Не с островов, а... чуть подальше. Объясним по дороге.','',0),
(302449,'ruRU','','Ну хорошо. Время не терпит, поэтому начнем подготовку. Спасибо всем за помощь. Зефрис перед вами в долгу.',0),
(302631,'ruRU','','Aonda is a good woman, and a true servant of Zephras Isle. It is my hope that you can quickly earn her trust and help her to keep Shen''dar Village safe. May the winds guide you, $n.',0),
(302649,'ruRU','','Ал''акир благословляет тебя. Но берегись: если решишь обмануть последователей Владыки Ветра, навлечешь на себя его гнев.',0),
(302650,'ruRU','<Двое сектантов разговаривают недалеко от вас. Можно спрятаться за шкафом и подслушать – вдруг проскочит что-то интересное.>','<Двое сектантов разговаривают недалеко от вас. Можно спрятаться за шкафом и подслушать – вдруг проскочит что-то интересное.>',0),
(302703,'ruRU','<The skyborne before you sways unsteadily, clearly very inebriated.>
\n
\nI used to be a sailor, you know? Before the trouble started. The skycutters used to run between the islands. Now it''s unsafe or some such, or so they say.
\n
\nI see the High Order and the Windshapers have their skycutters running again, but I''m stuck here, grounded!
\n
\nWhat aren''t we being told!
\n
\n<He turns and yells loudly at the innkeeper.>
\n
\nWHAT AREN''T WE BEING TOLD, DONAAL!?','',0),
(302705,'ruRU','Я говорю, народ, проклятый это лес! Я СВОИМИ ГЛАЗАМИ *ик* ВИДЕЛ!','',0),
(302706,'ruRU','Если мне не веришь, иди и посмотри! Дикие ветряные умертвия *ик*... Лесные духи грызут за лодыжки!','',0),
(302707,'ruRU','Там даже есть злобный лесной призрак! Весь в черном и... жуткий такой! Проклятый лес, про-кля-тый! *ик*','',0),
(302807,'ruRU','Если у тебя есть дар к друидскому искусству, я могу научить.','Если у тебя есть дар к друидскому искусству, я могу научить.',0),
(302809,'ruRU','The followers of the old Highborne ways have never been more hungry to gain knowledge and reclaim what we''ve lost. If you would seek to wield the power of the arcane and have the aptitude, I can help you take your next steps.','The followers of the old Highborne ways have never been more hungry to gain knowledge and reclaim what we''ve lost. If you would seek to wield the power of the arcane and have the aptitude, I can help you take your next steps.',0),
(302811,'ruRU','Зефрис срочно нуждается в охотниках и следопытах. Ветра бушуют все суровее, а магия уже не так надежно скрепляет наш остров. Дикие леса одичали еще сильнее, и только мы с соратниками можем защитить наш народ.
\n
\nЕсли у тебя есть дар к ремеслу охотника, я могу вооружить тебя знаниями о выживании в чаще.','Зефрис срочно нуждается в охотниках и следопытах. Ветра бушуют все суровее, а магия уже не так надежно скрепляет наш остров. Дикие леса одичали еще сильнее, и только мы с соратниками можем защитить наш народ.
\n
\nЕсли у тебя есть дар к ремеслу охотника, я могу вооружить тебя знаниями о выживании в чаще.',0),
(302814,'ruRU','Рази врагов и обольщай сердца одним простым трюком.
\n
\nЕсли пойдешь по пути разбойника, я могу тебя обучить... за кое-какую плату, конечно.','Рази врагов и обольщай сердца одним простым трюком.
\n
\nЕсли пойдешь по пути разбойника, я могу тебя обучить... за кое-какую плату, конечно.',0),
(302815,'ruRU','Хотя духи ветра нас покинули, сила стихий потеряла с нами связь не полностью... Если хватит терпения ее добиться.
\n
\nЯ помогаю посвященным в тайны шаманизма постигнуть их глубже.','Хотя духи ветра нас покинули, сила стихий потеряла с нами связь не полностью... Если хватит терпения ее добиться.
\n
\nЯ помогаю посвященным в тайны шаманизма постигнуть их глубже.',0),
(302817,'ruRU','Миг сомнения стоит воину жизни. Если ты не боишься смотреть смерти в лицо, я отучу тебя сомневаться.','Миг сомнения стоит воину жизни. Если ты не боишься смотреть смерти в лицо, я отучу тебя сомневаться.',0),
(302821,'ruRU','Хочешь научиться кожевничеству?','Хочешь научиться кожевничеству?',0),
(302824,'ruRU','You might think that just because we live on a floating island, there would be no need for miners like me. After so many thousands of years, however, we still manage to dig up a lot of interesting things.
\n
\nIt''s almost like there''s some invisible force, constantly creating new mineral deposits every so often. That''s magic for you though, right?
\n
\nRegardless, if you need training as a miner, then I''m your shen''dorei.','You might think that just because we live on a floating island, there would be no need for miners like me. After so many thousands of years, however, we still manage to dig up a lot of interesting things.
\n
\nIt''s almost like there''s some invisible force, constantly creating new mineral deposits every so often. That''s magic for you though, right?
\n
\nRegardless, if you need training as a miner, then I''m your shen''dorei.',0),
(303598,'ruRU','','Oh, and a word of warning before you head up to Shadowgale Forest. It''s incredibly dangerous up there. Some even say it''s haunted. Make sure you are prepared and well-equipped if you plan to make the trek.',0),
(303612,'ruRU','Добро пожаловать в таверну "Спокойный бриз". Желаешь перекусить или освежиться?','Добро пожаловать в таверну "Спокойный бриз". Желаешь перекусить или освежиться?',0),
(304010,'ruRU','Что тебе нужно, дитя Зефриса?','',0),
(304012,'ruRU','','Чем один Ваятель Ветра может послужить другому?',0),
(304013,'ruRU','','Я вижу по твоей ауре, что в тебе кровь высокорожденных. У представителей Высшего ордена мало общего с нашей фракцией Ваятелей Ветра. Если не считать относительного мира Тендалской рощи, раскол между нами пролегает очень глубоко. Так глубоко, что доходит до вражды и даже кровопролития.
\n
\nВ странствиях по Зефрису никогда не забывай, на чьей ты стороне. И еще хочу предупредить... не зли Ваятелей Ветра.',0),
(304014,'ruRU','Приветствую новопосвященного от имени Высшего ордена.','',0),
(304015,'ruRU','Приветствую… Ваятель ветра.
\n
\nТе, кто зовет себя Ваятелями ветра, находят мало общего с большинством членов Высшего ордена, как ты, должно быть, знаешь. За пределами относительного согласия Рощи Тендал ты убедишься, что эти разногласия очень глубоки и соперничество порой переходит в открытое насилие.
\n
\nБольше я ничего об этом не скажу, кроме одного: занимайся своими делами и не мешай целям Высшего ордена, когда покинешь рощу. Это, вероятно, единственное предупреждение, которое ты получишь.','',0),
(304291,'ruRU','Лортуна проводит там какой-то обряд. Она может попытаться обрушить защитные чары!
\n
\nПомощь, за которой мы послали, еще не пришла, но придется обойтись тем, что есть. Когда будешь $Gготов:готова;, скажи, и мы отправимся ее остановить.','',0),
(304299,'ruRU','','Лортуна! Прекрати это безумие. Ты понятия не имеешь, что случится после разрушения оберегов. Ты можешь обречь нас всех на гибель!',0),
(304303,'ruRU','','Айесса... моя бывшая сестра. Как же низко ты пала, если якшаешься с гадинами из Высшего ордена.',0),
(304304,'ruRU','Я с тобой церемониться не буду, ведьма. Заканчивай свои игры, и я убью тебя быстро. Не торгуйся – ничего лучше ты от Высшего ордена не добьешься.','',0),
(304307,'ruRU','','После разрушения оберегов? Глупцы! Обереги уже несколько дней как разрушены. Нет, я просто зажигаю маяк... для истинных служителей Ал''акира.',0),
(304433,'ruRU','','Наконец-то! Наш призыв услышан. Покоритесь погибели с радостью!',0),
(304441,'ruRU','Кто смеет призывать повелителя восточного ветра?','',0),
(304443,'ruRU','Так слухи оказались правдой. Мои своенравные братья хорошо спрятали это место от взора Ал''акира.','',0),
(304445,'ruRU','','Да! Да! Врата к Зефрису – моя заслуга! Представь меня своему Владыке Ветра, чтобы он признал вестницу его величия!',0),
(304447,'ruRU','Решила мне приказывать, смертная? Ошибаешься. Прочь с дороги, жалкая эльфийка!','',0),
(304448,'ruRU','','Нет! Никогда! Я бы никогда не посмела!',0),
(304449,'ruRU','Это точно, червь. Больше не посмеешь. Ха!','',0),
(304452,'ruRU','Живите свои жалкие жизни во владениях моего повелителя до его неизбежного приговора. Рано или поздно его суд вас настигнет.','',0),
(304454,'ruRU','Теперь, когда это чудесное царство больше от нас не скрыто, вы познакомитесь с НАСТОЯЩИМИ детьми Небесной выси...','',0),
(304558,'ruRU','Кончай трепаться, Полоскун. Последних клиентов распугаешь своими пьяными байками про привидений!','Кончай трепаться, Полоскун. Последних клиентов распугаешь своими пьяными байками про привидений!',0),
(304612,'ruRU','Добро пожаловать в деревню Шен''дар, тут одна из лучших рыбалок по эту сторону горного хребта. Если хочешь научиться ловить рыбу, могу научить – за плату.','',0),
(304626,'ruRU','','Столько всего, что мне уже страшно. Шайка бандитов поселилась в пещере к северу и устраивает налеты. А на юге культ Ал''акет недавно захватил деревню Фалаат. Я доверяю каждому миротворцу и поселянину, но таким малым числом невозможно защитить деревню.
\n
\nЕсли культ решит двигаться дальше в нашу сторону, мы едва ли их остановим.',0),
(304681,'ruRU','<Из-под металлических пластин брони создания доносится слабое жужжание. Ветер, приводящий эту машину в движение, едва теплится и лишь слегка шевелится. Не нужно много знать о воздушных созданиях, чтобы понять: этот образец явно нуждается в ремонте.>','<Из-под металлических пластин брони создания доносится слабое жужжание. Ветер, приводящий эту машину в движение, едва теплится и лишь слегка шевелится. Не нужно много знать о воздушных созданиях, чтобы понять: этот образец явно нуждается в ремонте.>',0),
(304790,'ruRU','Что ты здесь делаешь? Быстро уходи отсюда. Ты все испортишь!','',0),
(304794,'ruRU','Нет, нет! Лортуна, ты не понимаешь. Этот ваятель ветра просто проходил мимо и пришел сюда не со мной!','',0),
(304796,'ruRU','Лортуна, будь благоразумна. Элаадрин послал меня обсудить путь к миру и…','',0),
(304808,'ruRU','<Вращающийся перед тобой столб ветра, кажется, тихонько гудит от удовольствия. Говорить он не умеет, но ты ясно ощущаешь его чувства. Похоже, он… рад даровать тебе благословение ветров.>','<Вращающийся перед тобой столб ветра, кажется, тихонько гудит от удовольствия. Говорить он не умеет, но ты ясно ощущаешь его чувства. Похоже, он… рад даровать тебе благословение ветров.>',0),
(305044,'ruRU','Зефрис в великой опасности. Духи ветра привели наш народ в Небесную высь тысячи лет назад, но теперь они покинули нас и оставили без защиты в этом непрочном измерении. Когда-то наше процветающее общество населяло несколько заповедных островов Небесной выси, а сейчас мы даже точно не знаем, что случилось с шен''дорай на других островах.
\n
\nМы переживаем тяжелые времена, но Высший орден не перестанет бороться за наше будущее.','',0),
(305106,'ruRU','Прости за опоздание, Айесса.','',0),
(305107,'ruRU','Не сразу я уговорил верховного мага Ронина помочь мне с межпространственным порталом...','',0),
(305108,'ruRU','Ansirem! This isn''t how I expected our first meeting to go, but I''m glad you made it!','',0),
(305109,'ruRU','','Я тоже по-другому представляла нашу первую встречу, Мулн.',0),
(305110,'ruRU','Прямо на слезу прошибает. У длинноухих, оказывается, есть друзья из... откуда-то снизу.','',0),
(305111,'ruRU','Мы не ссорились с тобой, повелитель восточного ветра. Не тревожь нас.','',0),
(305112,'ruRU','Хорошо, смертные. Пока что я сжалюсь над вами. Мне не терпится рассказать обо всем Владыке Ветра. Мы с вами еще встретимся... очень скоро.','',0),
(305131,'ruRU','','Пустые угрозы, Элаадрин. Даже если вы схватите меня, мой великий труд подошел к концу. Вам повезло: вы очутились в оке бури в нужный момент и увидите плоды наших стараний своими глазами.',0),
(305132,'ruRU','Подождите... Где мы? Откуда все это во владениях Владыки Ветра?','',0),
(305133,'ruRU','Нам пора уходить. Я открою портал в Валанаар.','',0),
(305134,'ruRU','','Мулн Гнев Земли из Служителей Земли – Ваятели Ветра примут тебя как дорогого гостя.',0),
(305135,'ruRU','Приветствуем и тебя, верховный маг Руномант. Высший орден очень интересуется Кирин-Тором.','',0),
(305160,'ruRU','Искатель приключений! Мост ветра к другому шпилю держится непрочно. Подожди со мной, пока он не появится снова.','Искательница приключений! Мост ветра к другому шпилю держится непрочно. Подожди со мной, пока он не появится снова.',0),
(305322,'ruRU','','Приветствую и добро пожаловать, $n! Ты как раз вовремя: нашей компании «Снабжение и логистика Дуротара» всегда нужны новые подрядчики.
\n
\nЕсли ты умеешь добывать полезные материалы или создавать что-то с нуля, для тебя здесь найдется место.
\n
\nЕсли будут вопросы, дай знать.',0),
(305506,'ruRU','На что $Gуставился:уставилась;?','На что $Gуставился:уставилась;?',0),
(305765,'ruRU','Небоходы и паромы не ходят уже много лет. Кто знает, остались ли еще острова, откуда можно получать товары. Но я все равно здесь… на всякий случай.','Небоходы и паромы не ходят уже много лет. Кто знает, остались ли еще острова, откуда можно получать товары. Но я все равно здесь… на всякий случай.',0),
(305849,'ruRU','Верховная жрица, мы готовы исполнить твою волю. Я поведу наступление на западную дозорную башню, а полковник Циклий возглавит атаку на деревню Шен''дар. Мы займем оба пункта к завтрашнему утру.','Верховная жрица, мы готовы исполнить твою волю. Я поведу наступление на западную дозорную башню, а полковник Циклий возглавит атаку на деревню Шен''дар. Мы займем оба пункта к завтрашнему утру.',0),
(305850,'ruRU','','Небесный жрец Аандерс, мы близимся к нашей цели. От твоего успеха зависит многое.',0),
(305851,'ruRU','Конечно, верховная жрица. Мы твои послушные орудия. Я желаю лишь одного – чтобы ты узрела наш триумф лично.','Конечно, верховная жрица. Мы твои послушные орудия. Я желаю лишь одного – чтобы ты узрела наш триумф лично.',0),
(305852,'ruRU','','У меня сейчас другие дела, а ваша роль – лишь одна из фигур на доске. Не подведи меня, Аандерс.',0),
(305853,'ruRU','Да, верховная жрица!','Да, верховная жрица!',0),
(305854,'ruRU','Ты просишь благословение у Владыки Ветра?','Ты просишь благословение у Владыки Ветра?',0);
INSERT IGNORE INTO `broadcast_text_locale` (`ID`,`locale`,`Text_lang`,`Text1_lang`,`VerifiedBuild`) VALUES
(306235,'ruRU','Я не держу обиды на отдельных членов Ваятелей Ветра вроде тебя, но и развлекать разговорами не собираюсь. Ступай по своим делам, однако запомни: пока ты на острове, лучше обходи стороной Высший орден и наших агентов.
\n
\nВысший орден не провоцирует конфликтов... Но он их радикально заканчивает, если нас куда-то все же втягивают. Не путайся у нас под ногами, Ваятель Ветра.','',0),
(306273,'ruRU','I hope that your interruption is for a good cause. I was in the middle of some important work.','I hope that your interruption is for a good cause. I was in the middle of some important work.',0),
(306274,'ruRU','Ветра приветствуют тебя, друг. Чем я могу помочь?','Ветра приветствуют тебя, друг. Чем я могу помочь?',0),
(306276,'ruRU','А, привет. Вижу, ты хочешь задать мне вопрос.','А, привет. Вижу, ты хочешь задать мне вопрос.',0),
(306278,'ruRU','Да благословят тебя ветра судьбы. Чем могу помочь?','Да благословят тебя ветра судьбы. Чем могу помочь?',0),
(306574,'ruRU','$n, подготовь союзников к будущей битве с Лортуной и поговори со мной, когда решишь начать.','',0),
(306575,'ruRU','','$n, убедись, что все твои союзники готовы к бою, и поговори со мной, когда будешь $Gготов:готова; сразиться с Лортуной.',0),
(306593,'ruRU','<Следопыт не отрывает взгляд от огромного опорного столпа вдалеке.>','<Следопыт не отрывает взгляд от огромного опорного столпа вдалеке.>',0),
(306711,'ruRU','<Страж смерти Биллмут рассеянно ерзает и нервно озирается. Ему явно очень не по себе здесь.>','<Страж смерти Биллмут рассеянно ерзает и нервно озирается. Ему явно очень не по себе здесь.>',0),
(307118,'ruRU','<Before you lies the corpse of Jorel Windsinger.
\n
\nDeep lacerations are cut into his legs, and lightning burns scorch his fur.
\n
\nIt is clear he put up a fight before succumbing to his wounds.>','<Before you lies the corpse of Jorel Windsinger.
\n
\nDeep lacerations are cut into his legs, and lightning burns scorch his fur.
\n
\nIt is clear he put up a fight before succumbing to his wounds.>',0),
(307316,'ruRU','The spirit of strength does not always refer to physical strength. To face adversity both from within and without is what it means to take my shape.','',0),
(307829,'ruRU','Приветствую, охотник. Я могу научить тебя умениям и приемам.','Приветствую, охотник. Я могу научить тебя умениям и приемам.',0),
(307912,'ruRU','Следи за языком, |3-6($c). Ваятели Ветра не потерпят оскорблений от Высшего ордена.','Следи за языком, |3-6($c). Ваятели Ветра не потерпят оскорблений от Высшего ордена.',0),
(307942,'ruRU','Добро пожаловать в Валанаар, |3-6($c).','',0),
(307944,'ruRU','Не забывай наведываться к Высшему ордену – вдруг мы найдем тебе какое-нибудь поручение. А пока удачи в путешествиях!','',0),
(308149,'ruRU','Эй, чего тебе?','Эй, чего тебе?',0),
(309474,'ruRU','<Before you lies a skyborne; his body is mangled and bruised but still recognizable. It is clear he met a gruesome end while attempting to flee.
\n
\nIt appears that all of his belongings are still on his body, and a half-filled crate nearby lies spilled on the ground.>','',0),
(309795,'ruRU','','<Валенниа морщится от боли, поворачиваясь к тебе.>
\n
\nНе смотри на меня так. Со мной все будет в порядке. Несмотря на все усилия встревоженных целителей Верховного старейшины, я скоро буду на ногах и снова готова драться.
\n
\nА теперь ступай… не задерживайся из-за старого солдата. Ветры принесут тебе удачу в пути, я знаю.',0),
(309828,'ruRU','Да пребудет с тобой ветер, друг. Мне поручили открыть небеснорожденным путь напрямую в Штормград. Можешь пользоваться порталом в любое время.','',0),
(309857,'ruRU','','Пожалуйста, не трогайте флаконы, если не собираетесь их купить.
\n
\nОтпечатки пальцев портят их ценность, понимаете ли.',0),
(309858,'ruRU','Лучшего снаряжения ты нигде не найдешь!','',0),
(309859,'ruRU','О! Приветствую, друг. Не стесняйся, смотри мои товары.','',0),
(309860,'ruRU','Эй, чего надо?','',0),
(309861,'ruRU','','Приветствую, друг! У меня большой запас кожи и шкур, и я знаю пару приемов, которыми, пожалуй, готов поделиться. Хочешь торговать?',0),
(309862,'ruRU','<Джим''бек встречается с тобой взглядом, глубоко затягиваясь кальяном.>
\n
\nЗдорово, мон. Нужен ковер? Одеяло? Или просто ткань для следующей поделки? Я тебе все достану.','',0),
(309993,'ruRU','','Ишну-алах, путник, и добро пожаловать в Ночную Гавань.
\n
\nХочешь взглянуть на мой выбор красивых платьев?',0),
(311965,'ruRU','Еще одно новое лицо! Добро пожаловать в Азерот, приятель. Приходи ко мне, если нужна помощь, чтобы встать на ноги.
\n
\nС деньгами.','Еще одно новое лицо! Добро пожаловать в Азерот, приятель. Приходи ко мне, если нужна помощь, чтобы встать на ноги.
\n
\nС деньгами.',0),
(312188,'ruRU','Камень и земля говорят правдивее любого языка, если унять грохот в сердце и прислушаться.
\n
\nЕсли в тебе есть задатки шамана, я тебя научу.','Камень и земля говорят правдивее любого языка, если унять грохот в сердце и прислушаться.
\n
\nЕсли в тебе есть задатки шамана, я тебя научу.',0),
(312224,'ruRU','Ты уже $Gнашел:нашела; то, что нам нужно?','Ты уже $Gнашел:нашела; то, что нам нужно?',0),
(312713,'ruRU','Скучно мне тут наверху. Всех развлечений – побесить противного зануду Халаана, да и то быстро надоедает.','Скучно мне тут наверху. Всех развлечений – побесить противного зануду Халаана, да и то быстро надоедает.',0),
(312724,'ruRU','Эй! Осторожней там! Священные дары шен''дорай – это тебе не игрушка!','',0),
(312725,'ruRU','Эх... Молодежь!','',0),
(312929,'ruRU','Не хочу тебя расстраивать, |3-6($c), но у тебя пока мало опыта для островов Черного Копья.','Не хочу тебя расстраивать, |3-6($c), но у тебя пока мало опыта для островов Черного Копья.',0),
(313248,'ruRU','Присаживайся к огню, и мы начнем.','',0),
(313249,'ruRU','Чтобы разбить лагерь, надо всего лишь развести костер. Учителя кулинарии покажут тебе, как.','',0),
(313250,'ruRU','После костра переходи к другим объектам и расставляй их вокруг.','',0),
(313251,'ruRU','Умелые кожевники, например, могут натянуть палатку – вроде той, что позади меня.','',0),
(313253,'ruRU','В любой профессии есть свои преимущества для лагеря, даже у рыбной ловли!','',0),
(313254,'ruRU','А потом остается только сесть и погреться у костра. Через несколько минут отдыха ты получишь ауры, которые помогут в путешествиях.','',0),
(313255,'ruRU','Если задержишься еще на пару секунд, моя палатка тоже передаст тебе полезную ауру.','',0),
(313256,'ruRU','Вот, собственно, и все. Как только получить ауру от костра, поговори со мной еще раз.','',0),
(313261,'ruRU','Здравствуй, путник!','',0),
(313452,'ruRU','Вы уже видели? Неборезы снова вышли из гаваней! Правда, движения между шен''дорайскими островами все равно пока нет.
\n
\nНадеюсь, мы скоро восстановим маршруты к Шен''драмару и Элдранаару... Если от них что-то осталось.','Вы уже видели? Неборезы снова вышли из гаваней! Правда, движения между шен''дорайскими островами все равно пока нет.
\n
\nНадеюсь, мы скоро восстановим маршруты к Шен''драмару и Элдранаару... Если от них что-то осталось.',0),
(313453,'ruRU','Ваятели Ветра и Высший орден что-то затевают. Ходят слухи, что обе фракции планируют снова запустить неборезы и сбежать на них из Небесной выси. Сбежать из Небесной выси! Просто смешно. И куда они тогда пойдут?','Ваятели Ветра и Высший орден что-то затевают. Ходят слухи, что обе фракции планируют снова запустить неборезы и сбежать на них из Небесной выси. Сбежать из Небесной выси! Просто смешно. И куда они тогда пойдут?',0),
(313454,'ruRU','Если мы срочно не остановим культ Ал''акет, нас всех загребут в фанатики. А мне категорически не идет бритая голова.','Если мы срочно не остановим культ Ал''акет, нас всех загребут в фанатики. А мне категорически не идет бритая голова.',0),
(313455,'ruRU','Ты знаешь, что случилось с Бан''эталом? Миротворцы запрещают подходить к руинам и вообще к Теневейному лесу.
\n
\nКто-то в таверне болтал про злобных духов ветра. Якобы они являются в виде туманного силуэта, как будто... из них вынули сердцевину.
\n
\nМурашки по коже от таких мыслей.','Ты знаешь, что случилось с Бан''эталом? Миротворцы запрещают подходить к руинам и вообще к Теневейному лесу.
\n
\nКто-то в таверне болтал про злобных духов ветра. Якобы они являются в виде туманного силуэта, как будто... из них вынули сердцевину.
\n
\nМурашки по коже от таких мыслей.',0),
(313456,'ruRU','Неборезы все чаще проходят по небесам. Хорошо, что их сумели запустить снова. Если бы еще старейшины рассказали нам, что происходит... Они продолжают твердить, что ничего не изменилось и связи с другими островами нет.
\n
\nЯ постоянно ломаю голову над всеми этими загадками...','Неборезы все чаще проходят по небесам. Хорошо, что их сумели запустить снова. Если бы еще старейшины рассказали нам, что происходит... Они продолжают твердить, что ничего не изменилось и связи с другими островами нет.
\n
\nЯ постоянно ломаю голову над всеми этими загадками...',0),
(313457,'ruRU','Культ Ал''акет перерастает в серьезную проблему, и миротворцы не в состоянии его остановить. Можно только надеяться, что Ваятели Ветра и Высший орден отложат свои пререкания, чтобы вместе с миротворцами озаботиться нашей защитой.
\n
\nМне вообще не хочется вступать ни в какие культы!','Культ Ал''акет перерастает в серьезную проблему, и миротворцы не в состоянии его остановить. Можно только надеяться, что Ваятели Ветра и Высший орден отложат свои пререкания, чтобы вместе с миротворцами озаботиться нашей защитой.
\n
\nМне вообще не хочется вступать ни в какие культы!',0),
(313458,'ruRU','Культ Ал''акет утверждает, что "Владыка Ветра" Ал''акир спасет нас от бед на Зефрисе. Если Ал''акира не выдумали и он в самом деле правит Небесной высью, почему духи ветра так долго отказывались о нем говорить?
\n
\nИли его не существует, или хуже – он существует и сектанты сильно приукрасили его доброту. В любом случае, для простых эльфов вроде нас ничем хорошим не кончится.','Культ Ал''акет утверждает, что "Владыка Ветра" Ал''акир спасет нас от бед на Зефрисе. Если Ал''акира не выдумали и он в самом деле правит Небесной высью, почему духи ветра так долго отказывались о нем говорить?
\n
\nИли его не существует, или хуже – он существует и сектанты сильно приукрасили его доброту. В любом случае, для простых эльфов вроде нас ничем хорошим не кончится.',0),
(313459,'ruRU','Be wary of anyone you meet with grey robes and a shaved head. They call themselves the Al''Aketh, and they are a menace. 
\n
\nI even heard that they''ve been doing things to the anchor pylons around the island.
\n
\nIf the Windshapers are to be believed, those pylons are the only thing keeping Zephras afloat here in the elemental plane. It would be madness to tamper with them!','Be wary of anyone you meet with grey robes and a shaved head. They call themselves the Al''Aketh, and they are a menace. 
\n
\nI even heard that they''ve been doing things to the anchor pylons around the island.
\n
\nIf the Windshapers are to be believed, those pylons are the only thing keeping Zephras afloat here in the elemental plane. It would be madness to tamper with them!',0),
(313486,'ruRU','Приветствую тебя, путник.','Приветствую тебя, путница.',0),
(313648,'ruRU','Ночекогти не придут в восторг от дерзких лазутчиков. Соблюдай осторожность в Теневейном лесу, |3-6($c).','',0),
(314601,'ruRU','Подожди, да... этот кристалл! Валенния, это...','',0),
(314602,'ruRU','','...кристалл возвращения для записи важных событий.',0),
(314603,'ruRU','Перебежчик надеялся предложить его нам в обмен на защиту.','',0),
(314604,'ruRU','','Но кристалл сильно поврежден. Запись, скорее всего, тоже пострадала, поэтому надо тщательнее прислушиваться.',0),
(314605,'ruRU','Активируй его, Валенния. Нужно узнать как можно больше из этих данных.','',0),
(314606,'ruRU','','...безотлагательно. Немедленно собирайте войска в поход. Столпы – главная опора, а... обереги... исчезнет. Это...',0),
(314607,'ruRU','','...скорее. Наша армия... уязвимость... мой ритуал нельзя...',0),
(314608,'ruRU','','Я одна... эта задача... Владыка Ветра... наши голоса... он придет... последний шанс!',0),
(314609,'ruRU','','Боюсь, из кристалла больше ничего не выжмешь.',0),
(314610,'ruRU','Обереги... что там было про обереги, Валенния?','',0),
(314611,'ruRU','','Опорные столпы удерживают нас в воздухе и к тому же выполняют роль оберегов! Шал''нан об этом упоминал. Они защищают нас от...',0),
(314612,'ruRU','...всех остальных обитателей Небесной выси. Да спасут нас духи... Так вот в чем ее план. Разрушить обереги и впустить своего "Владыку Ветра"!','',0),
(315474,'ruRU','Добро пожаловать в гильдейскую регистратуру Валанаара. Чем могу помочь?','Добро пожаловать в гильдейскую регистратуру Валанаара. Чем могу помочь?',0),
(316076,'ruRU','Мы, паладины, должны каждый день заслуживать свое место среди собратьев-Отрекшихся, чтобы нас не сочли фанатиками вроде Алого ордена. Свет – не просто орудие наших врагов, а проводник нашей праведной ярости! Именно благодаря преданности Темной Госпоже и любви к родному краю мы можем направлять Свет, чтобы нести правосудие нашим врагам.
\n
\nКоролева-банши зорко следит за нами. Пусть следит. Она увидит, что наша решимость не дрогнет. Мы – Отрекшиеся!','',0),
(316310,'ruRU','Нам необходимо узнать больше о замыслах культа, но эта важнейшая информация могла умереть вместе с перебежчиком...','',0),
(316364,'ruRU','','Наверное, так и есть. Я и другие мои элитные бойцы раньше состояли в ордене "Поднебесные клинки". Мы служили личной стражей нашего бывшего правителя Шал''нана.
\n
\nВ нынешние неспокойные времена мы в меру своих сил командуем гражданским ополчением миротворцев: мы на Зефрисе единственные более-менее профессиональные солдаты.',0),
(316366,'ruRU','','<Валенния ненадолго отводит взгляд, а затем нерешительно смотрит на вас.>\n\nШал''нан был лучшим из нас. Это он выступил в защиту нашего народа от безумия и угнетения в Эльдре''Таласс почти десять тысяч лет назад. Это Шал''нан провел нас через неизведанное море, чтобы спастись от кровожадной мести наших древних врагов.\n\nЭто Шал''нан заключил договор о дружбе с духами ветра, благодаря которому мы смогли подняться к Небесной стене... и выжить.\n\nОн всегда был слугой-вождем своего народа, даже после того, как отказался от власти и удалился от дел.',0),
(316368,'ruRU','','Большинство шен''дорай разве что перемолвилось с ним парой слов. Наверное, из более тесных знакомств только я дожила до сегодняшнего дня.
\n
\nЯ служила капитаном "Поднебесных клинков" почти девять сотен лет, пока однажды он не... покинул нас.
\n
\nНо даже я не могу сказать, что по-настоящему его знала. Он держался отстраненно и предпочитал одиночество. Проводил большую часть времени в уединении или в разговорах с духами на высоких шпилях над святилищем Четырех Ветров... Сектанты теперь называют его святилищем Акира.',0),
(316370,'ruRU','','Если бы я знала, жить на Зефрисе было бы намного проще. Эта тайна вызывает среди нас бессчетные беды и раздоры.
\n
\nЯ не виню тебя за любопытство, но больше ничего об этом сказать сейчас не могу.',0),
(316402,'ruRU','Если ты не прочь поучиться, могу показать, как обращаться с кузнечным молотом.','Если ты не прочь поучиться, могу показать, как обращаться с кузнечным молотом.',0),
(316763,'ruRU','<Зверь тихо щелкает клювом.>','',0),
(316767,'ruRU','<Буреног издает мягкое воркотание, когда вы подходите ближе.>','',0),
(316769,'ruRU','<Буреног смотрит на вас с неприкрытым восторгом. Кажется, птица слегка подпрыгивает в нетерпении.>','',0),
(316772,'ruRU','<Мясистые уши на его черепе слегка поворачиваются на атрофированных мышцах.>','',0),
(316813,'ruRU','<Оно скребет землю щербатым копытом.>','',0),
(316815,'ruRU','<Его глубокие пустые глазницы, кажется, сверлят тебя.>','',0),
(316817,'ruRU','<Оно щелкает зубами, грызя удила.>','',0),
(316839,'ruRU','Отличный выбор. Я отметил это место на твоей карте.','Отличный выбор. Я отметил это место на твоей карте.',0),
(316863,'ruRU','Добро пожаловать в мою лавку; приятно видеть еще одного портного здесь, в Валанааре. Не за уроком ли $Gпришел:пришела;?','Добро пожаловать в мою лавку; приятно видеть еще одного портного здесь, в Валанааре. Не за уроком ли $Gпришел:пришела;?',0),
(317077,'ruRU','Добро пожаловать в мою лавку; приятно видеть еще одного зачарователя здесь, в Валанааре. Не за уроком ли $Gпришел:пришела;?','Добро пожаловать в мою лавку; приятно видеть еще одного зачарователя здесь, в Валанааре. Не за уроком ли $Gпришел:пришела;?',0),
(318281,'ruRU','Welcome to Fairweather Stables! I would love to provide you with one of our fine galestriders, but it seems like you may not yet have enough experience to ride one.
\n
\nThey are temperamental at times and are prone to toss newer riders if not handled correctly. I would be more than happy to provide the training for you once you are a more seasoned adventurer and have enough coin!','Welcome to Fairweather Stables! I would love to provide you with one of our fine galestriders, but it seems like you may not yet have enough experience to ride one.
\n
\nThey are temperamental at times and are prone to toss newer riders if not handled correctly. I would be more than happy to provide the training for you once you are a more seasoned adventurer and have enough coin!',0),
(319470,'ruRU','С-слизь! Р-ра-а...','',0),
(320568,'ruRU','Приветствую.','Приветствую.',0),
(321113,'ruRU','Да проклянет буря этих фанатиков из Ал''акета!','Да проклянет буря этих фанатиков из Ал''акета!',0),
(321197,'ruRU','Добро пожаловать в банк Валанаара. Твое ценное имущество будет у нас в безопасности. Хочешь проверить свою ячейку?','Добро пожаловать в банк Валанаара. Твое ценное имущество будет у нас в безопасности. Хочешь проверить свою ячейку?',0),
(321203,'ruRU','Тебе удалось заслужить доверие Когтя Ночи, |3-6($c). Нам нечего предложить тебе в награду, – но есть чертежи, добытые в руинах Бан''этала.
\n
\nМаги-кузнецы Бан''этала считались лучшими мастерами на Небесных островах. Друиды Когтя Ночи пользуются дарами природы, так что чертежи ремесленников нам ни к чему.
\n
\nПродолжай нас поддерживать, и я раскрою тебе их секреты.','',0),
(321408,'ruRU','Приветствую тебя, |3-6($c). Тебе нужно оружие?
\n
\nМоим наставником был Антарион из Бан''этала, и он обучил меня древним тайнам магов-кузнецов Калимдора.
\n
\nНа острове Зефрас не найти оружия лучше моего.','Приветствую тебя, |3-6($c). Тебе нужно оружие?
\n
\nМоим наставником был Антарион из Бан''этала, и он обучил меня древним тайнам магов-кузнецов Калимдора.
\n
\nНа острове Зефрас не найти оружия лучше моего.',0),
(321422,'ruRU','Ты найдешь Лотелума Звездный Ветер на утесе с видом на водопад. Это на восточном краю города.','Ты найдешь Лотелума Звездный Ветер на утесе с видом на водопад. Это на восточном краю города.',0),
(321462,'ruRU','Ищешь гонца? Он только что улетел, как пташка.
\n
\nНе виню беднягу. Эти вендиго – та еще напасть.','Ищешь гонца? Он только что улетел, как пташка.
\n
\nНе виню беднягу. Эти вендиго – та еще напасть.',0),
(321567,'ruRU','<Тело выглядит неполным и, кажется, ждет голову.>','<Тело выглядит неполным и, кажется, ждет голову.>',0),
(323922,'ruRU','Да, я тот самый знаменитый торговец, который великодушно прокормил... э-э, голодающих... детей?.. Подгорода во время недавней войны с Плетью. Это я – деловой гоблин-визионер и гений логистики, который лично вооружил ополчение и помог Темной Госпоже объединить целый народ вонючих трупов... то есть Отрекшихся.
\n
\nДа, это я. Гликс Ксиззикс. С радостью дам автограф. Не бесплатно, конечно.
\n
\nСпросишь, зачем я открыл тут парикмахерскую? Одно слово: диверсификация. Чем больше разных источников дохода, тем лучше!','',0),
(324145,'ruRU','','Несколько лет назад летающие острова что-то вывело из равновесия, и они начали отдаляться друг от друга. Мало того – теперь большие фрагменты Зефриса и вовсе падают вниз. Трудно представить, что твой дом в один прекрасный день обрушится в бездну, но мы теперь вот так живем.',0),
(324553,'ruRU','Быть может, мне стоит напомнить тебе, небовидица, что пролилась кровь Высшего ордена? Мы призовем виновных к ответу.','Быть может, мне стоит напомнить тебе, небовидица, что пролилась кровь Высшего ордена? Мы призовем виновных к ответу.',0),
(324554,'ruRU','','Кто бы говорил, чароплет. А как же Ваятели ветра, которых убил ваш агент на нагорье? Кто ответит за них?',0),
(324555,'ruRU','','Никто? Я так и думала. Скажи Элаадрину, что я до сих пор не собрала шаманов и не сбросила тебя и других шарлатанов с этого острова лишь из-за нынешнего кризиса.',0),
(324556,'ruRU','Но, небовидица, это же...','Но, небовидица, это же...',0),
(324561,'ruRU','Она смеет нам угрожать, после того как ее приспешники расправились с представителями ордена на нагорье?','',0),
(324562,'ruRU','Даже не знаю, кто опаснее – ал''акеты или эти проклятые небом Ваятели ветра! Что ж, ладно. Если она не намерена уладить этот конфликт цивилизованно, мы ответим ей, как только минует этот кризис.','',0),
(324563,'ruRU','А пока осведоми наш народ. Пусть все остерегаются Ваятелей ветра. Не мы начали эту войну, но мы закончим ее, как только разберемся с сектантами.','',0),
(324564,'ruRU','Будет сделано, верховный магистр!','',0),
(324914,'ruRU','В последнее время приливы и отливы магии нарушены. Слышал, даже маги Даларана в замешательстве. Это возмущение арканы – или сами стихии неспокойны?','В последнее время приливы и отливы магии нарушены. Слышал, даже маги Даларана в замешательстве. Это возмущение арканы – или сами стихии неспокойны?',0),
(324978,'ruRU','Чем я могу помочь?','',0),
(325026,'ruRU','Чего тебе?','',0),
(325030,'ruRU','Чем могу помочь?','Чем могу помочь?',0),
(325066,'ruRU','У меня лучшее мясо в Оргриммаре.','',0),
(325339,'ruRU','Э? Ты слишком зеленый, чтобы иметь со мной дело.
\n
\nВозвращайся, когда немного освоишься с тем, как тут все устроено. Поверь мне.','',0),
(325752,'ruRU','Для меня честь заниматься снабжением и провизией Служителей Земли. 
\n
\nМои запасы пока невелики, но заглядывай почаще – у меня могут появиться новое снаряжение и припасы на продажу.','Для меня честь заниматься снабжением и провизией Служителей Земли. 
\n
\nМои запасы пока невелики, но заглядывай почаще – у меня могут появиться новое снаряжение и припасы на продажу.',0),
(325810,'ruRU','Приветствую, гражданин. Чем могу помочь?','',0),
(325823,'ruRU','Добро пожаловать в Крепость Штормграда, гражданин.','',0),
(325825,'ruRU','Веди себя достойно в присутствии вождя, $c. Кор''кроны не потерпят здесь ни наглости, ни оскорблений.','',0),
(325830,'ruRU','Я Вол''джин из племени Черного Копья. Ты друг или враг?','',0),
(325833,'ruRU','','<Леди Сильвана Ветрокрылая молча смотрит на тебя.>',0),
(326162,'ruRU','The Wind Spirits have left us. 
\n
\nNow, only mindless echoes remain. Be wary, however. These winds are neither kind, nor gentle.','The Wind Spirits have left us. 
\n
\nNow, only mindless echoes remain. Be wary, however. These winds are neither kind, nor gentle.',0),
(326390,'ruRU','Если ты $Gпришел:пришла; искать братство своих собратьев-паладинов, ты по адресу. 
\n
\nДобро пожаловать домой.','Если ты $Gпришел:пришла; искать братство своих собратьев-паладинов, ты по адресу. 
\n
\nДобро пожаловать домой.',0),
(326576,'ruRU','Проследи, чтобы он сразу его прочел. Боюсь, наши проблемы с Плетью только начинаются.
\n
\nИ загляни ко мне через некоторое время. Кажется, я сделал кое-какое открытие и скоро мне потребуется умелый воин.','Проследи, чтобы он сразу его прочел. Боюсь, наши проблемы с Плетью только начинаются.
\n
\nИ загляни ко мне через некоторое время. Кажется, я сделала кое-какое открытие и скоро мне потребуется умелый воин.',0),
(326579,'ruRU','Мы заняты! Важные дела.','',0),
(326582,'ruRU','А, точно. Держи.','',0),
(326764,'ruRU','Моя работа – снабжать паладинов крепости Бандариона достойным оружием и доспехами. Немного, но честный труд.
\n
\nЕсть у меня кое-что на продажу, если тебе нужно снаряжение.','Моя работа – снабжать паладинов крепости Бандариона достойным оружием и доспехами. Немного, но честный труд.
\n
\nЕсть у меня кое-что на продажу, если тебе нужно снаряжение.',0),
(326872,'ruRU','Моя клятва привязывает меня к этому месту. Что привело тебя в это забытое Светом место?','',0),
(326948,'ruRU','Я Беланаа Вуаль Ветра, представитель Высшего ордена на Азероте. Буду признательна, если пожертвуешь немного ткани для нашей организации.','Я Беланаа Вуаль Ветра, представитель Высшего ордена на Азероте. Буду признательна, если пожертвуешь немного ткани для нашей организации.',0),
(326949,'ruRU','Я Мулн Гнев Земли из Служителей Земли. Что привело тебя ко мне сегодня?','',0),
(326951,'ruRU','Нам, шен''дорай, нужно больше ткани, чтобы пополнить запасы. Любые пожертвования пригодятся и непременно повысят твое уважение у Ваятелей ветра.','Нам, шен''дорай, нужно больше ткани, чтобы пополнить запасы. Любые пожертвования пригодятся и непременно повысят твое уважение у Ваятелей ветра.',0),
(326965,'ruRU','Нас теперь совсем мало, но среди шен''дорай еще остались изумрудные сновидцы.','',0),
(327145,'ruRU','Отсюда идет корабль до Даларана в Альтеракские горы.','',0),
(327146,'ruRU','Неборез возит пассажиров от этой пристани до Даларана.','',0),
(327153,'ruRU','Этот неборез доставит тебя прямо на великолепные открытые равнины Мулгора.','',0),
(327642,'ruRU','','Чем могу помочь?',0),
(327927,'ruRU','<Мертвый боевой конь склоняет голову набок и жует удила, разглядывая тебя.>','',0),
(327930,'ruRU','<Мертвый боевой конь вытягивает шею в твою сторону и смотрит на тебя двумя молочными немигающими глазами.>','',0),
(327932,'ruRU','<Боевой конь скребет землю, отчего нечестивое пламя вокруг его щербатого копыта колышется.>','',0),
(328028,'ruRU','<The strider stills its agitated movements and fixes you with its golden eyes.>','',0),
(328030,'ruRU','<The strider taps its talons on the moist soil.>','',0),
(328033,'ruRU','<The strider preens its feathers and looks at you quizzically.>','',0),
(328261,'ruRU','Добро пожаловать в парикмахерскую, друг! За стрижкой? Покраской? Чем-нибудь еще?
\n
\nМы можем подстричь бороду, сделать пирсинг, изменить бивни и рога и даже подправить черты нежити!
\n
\nПрисаживайся, и мы сразу приступим. Еще немного – и ты станешь новым, более привлекательным.','Добро пожаловать в парикмахерскую, друг! За стрижкой? Покраской? Чем-нибудь еще?
\n
\nМы можем подстричь бороду, сделать пирсинг, изменить бивни и рога и даже подправить черты нежити!
\n
\nПрисаживайся, и мы сразу приступим. Еще немного – и ты станешь новым, более привлекательным.',0),
(328288,'ruRU','Если хочешь подстричь гриву, загляни на нижний уступ напротив аукционистов.','Если хочешь подстричь гриву, загляни на нижний уступ напротив аукционистов.',0);
